Method.Implementation:
	Set tSC=$$$OK
	If pInput.%Extends("%FileBinaryStream") {
		$$$TRACE("CorpprvInFile creating document from XML file "_pInput.Filename)
		Set tDocIn=##class(EnsLib.EDI.XML.Document).%New(pInput.Filename)
	} Else {
		$$$sysTRACE("creating document from XML file stream "_pInput.Filename_" with TranslateTable='"_pInput.TranslateTable_"'")
		set indx=186
		set recHd=pInput.Read(indx,.sc)
		$$$TRACE("Record Head: "_recHd)
		set fStr=""
		set fStrCnt=1
		set hasBC=0
		For { Set tchar=pInput.Read(1,.sc)  Quit:tchar=""
           if (($ASCII(tchar) < 7)) {
              $$$TRACE("Found a special character:"_$ASCII(tchar)_" at "_indx)
          	  set hasBC=1
              Quit
           }
           else {
              set indx=indx+1
              if (fStrCnt<90) {
	              set fStr=fStr_tchar
	              set fStrCnt=fStrCnt+1
              }
              else {
	              set fStr=##class(Ens.Util.FunctionSet).SubString(fStr,2)_tchar
              }
           }
        }
        if (hasBC=1) {
	       set pid=##class(Ens.Util.FunctionSet).Piece(recHd,"<id>",2)
	       set pid=##class(Ens.Util.FunctionSet).Piece(pid,"</id>",1)
	       set status = ##class(IHC.ITF.ITFCOMMON.Utility).InputDataError(..%ConfigName, " Record with provider id: "_pid_", has at least one special character after this text: >>"_fStr_"<<")       
           Quit %objlasterror
        }
        else {
           do pInput.Rewind()
		   Set tDocIn=##class(EnsLib.EDI.XML.Document).%New(pInput)
        }
	}
	if tDocIn="" Quit %objlasterror
	 do{
	    Set reader = ##class(%XML.Reader).%New()
	    Set sc=reader.OpenString(tDocIn.RawContent)
 		if '$$$ISOK(sc){
     		set tSC=##class(IHC.ITF.ITFCOMMON.Utility).FailMsgError(.%ConfigName,"Error Processing Response Back From MSPR"_$SYSTEM.Status.GetOneErrorText(sc))  
     		quit
  		} 
 	   Else {
     	 Do reader.Correlate("CORPPRV_PROVIDER","IHC.ITF.DStruc.Schema.CORPPRVProviderRequest.CORPPRVPROVIDER")
     	 do reader.Next(.pRequest,.sc)
     	 If $$$ISOK(sc){
	     	 $$$TRACE("Send IHC.ITF.DStruc.Schema.CORPPRVProviderRequest.CORPPRVPROVIDER")
	 	    do ..SendRequestAsync(..TargetConfigNames,pRequest)
     	 }Else
     	 {     
            set status=##class(IHC.ITF.ITFCOMMON.Utility).FailMsgError(..%ConfigName,"Error Processing Response Back From MSPR"_$SYSTEM.Status.GetOneErrorText(sc))  
     	}    
  	}

  }while(0)  

  quit tSC

Do ##super(.pArray,pItem)
If pItem.GetModifiedSetting("TargetConfigNames",.tValue) {
	For i=1:1:$L(tValue,",") { Set tOne=$ZStrip($P(tValue,",",i),"<>W")  Continue:""=tOne  Set pArray(tOne)="" }
}
